sealed class ResponsiveChannelGrid : Panel {
 public int ChannelWidth=72;public bool SingleRow;bool arranging;public int Columns{get;private set;}
 public ResponsiveChannelGrid(){DoubleBuffered=true;AutoScroll=true;Padding=new Padding(4);}
 protected override void OnLayout(LayoutEventArgs e){if(arranging)return;arranging=true;try{for(int pass=0;pass<2;pass++){int count=Math.Max(1,Controls.Count);int width=Math.Max(1,ClientSize.Width-8);int columns=1;if(SingleRow)columns=count;else foreach(int candidate in new int[]{24,12,8,6,4,3,2,1})if(candidate<=count&&count%candidate==0&&candidate*ChannelWidth<=width){columns=candidate;break;}Columns=columns;int rows=(count+columns-1)/columns;int cellWidth=SingleRow?Math.Max(ChannelWidth,width/count):Math.Max(ChannelWidth,width/columns);int height=Math.Max(268,(ClientSize.Height-20)/rows);AutoScrollMinSize=new Size(SingleRow?cellWidth*count+8:0,height*rows+8);Point scroll=AutoScrollPosition;for(int i=0;i<Controls.Count;i++)Controls[i].Bounds=new Rectangle(4+(i%columns)*cellWidth+scroll.X,4+(i/columns)*height+scroll.Y,cellWidth-4,height-4);base.OnLayout(e);}}finally{arranging=false;}}
}

